local a=require"system.filesystem"local b=require"system.util"local c=assert(b.argparse({f=false,i=false,R="@r",r=false,["no-preserve-root"]=false},...))local d=true;for e,f in ipairs(c)do local g=a.stat(f)if not c["no-preserve-root"]and a.combine(f)=="/"then io.stderr:write("rm: refusing to remove root directory")elseif not g then if not c.f then io.stderr:write("rm: "..f..": No such file or directory\n")end;d=false elseif g.type=="directory"then if c.r then a.remove(f)else io.stderr:write("rm: -r not specified, skipping directory "..f.."\n")d=false end else a.remove(f)end end;return d
